def solve(nums):
    n = len(nums)
    if n < 2:
        return nums[:]
    # Find the first index i from the right where nums[i] < nums[i+1]
    i = n - 2
    while i >= 0 and nums[i] >= nums[i + 1]:
        i -= 1
    if i == -1:
        # Last permutation: return sorted ascending
        return sorted(nums)
    # Find the smallest element greater than nums[i] to the right (rightmost such)
    j = n - 1
    while nums[j] <= nums[i]:
        j -= 1
    # Swap and reverse suffix
    res = nums[:]
    res[i], res[j] = res[j], res[i]
    res[i + 1:] = reversed(res[i + 1:])
    return res

