def solve(nums):
    """Return the length of the longest strictly increasing subsequence.
    Implements patience sorting with binary search for O(n log n) time.
    """
    import bisect
    tails = []  # tails[i] = smallest possible tail of an increasing subsequence of length i+1
    for x in nums:
        # Find insertion point: leftmost index where tails[idx] >= x
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

