def solve(grid):
    # Handle empty grid
    if not grid:
        return 0
    rows = len(grid)
    # Determine max columns for safety
    max_cols = max((len(row) for row in grid), default=0)
    visited = [[False]*max_cols for _ in range(rows)]
    def get_val(r, c):
        # Return 0 for out-of-bounds column in ragged rows
        if c < 0 or c >= len(grid[r]):
            return 0
        return grid[r][c]
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            if i < 0 or i >= rows or j < 0 or j >= max_cols:
                continue
            if visited[i][j]:
                continue
            if get_val(i, j) == 0:
                visited[i][j] = True  # Mark as visited to avoid rechecking
                continue
            visited[i][j] = True
            stack.extend([(i-1, j), (i+1, j), (i, j-1), (i, j+1)])
    count = 0
    for i in range(rows):
        for j in range(len(grid[i])):  # iterate only actual columns
            if not visited[i][j] and get_val(i, j) == 1:
                count += 1
                dfs(i, j)
    return count

